sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

	try {

		var name = source.u_name ? source.u_name.trim() : "";
		var projectName = source.u_project_name ? source.u_project_name.trim() : "";

		var resGR = new GlideRecord('x_kp101_kpmg_res_0_resource_profile');
			resGR.addQuery('resource_name.name', name);
			resGR.query();

		if(!resGR.next()){
			gs.info("Resource not found: " + name);
			ignore = true;
			return;
		}

		var projGR = new GlideRecord('x_kp101_kpmg_res_0_project_assignment');
			projGR.addQuery('name', projectName);
			projGR.query();

		if(!projGR.next()){
			gs.info("Project not found: " + projectName);
			ignore = true;
			return;
		}
		gs.info("TEST USER1 " + resGR.sys_id);
		gs.info("TEST USER2 " + projGR.sys_id);
		target.user = resGR.sys_id;
		target.project_assignment = projGR.sys_id;


	} catch (err) {

		gs.info("Error: " + err.message);
		ignore = true;

	}

})(source, map, log, target);
